 async function askVyroAI(textValue){const isImage=textValue.startsWith('لطفاً برای این درخواست تصویر بساز:');const prompt=textValue.replace('لطفاً برای این درخواست تصویر بساز:','').trim();const messages=[...aiMessages.map(m=>({role:m.role==='assistant'?'assistant':'user',content:m.text})),{role:'user',content:textValue}];setAiMessages(prev=>[...prev,{role:'user',text:textValue}]);setAiLoading(true);try{if(!supabaseReady)throw new Error('service unavailable');const {data,error}=await supabase.functions.invoke('vyro-ai',{body:isImage?{imagePrompt:prompt}:{messages}});if(error)throw error;if(isImage){if(!data?.imageUrl)throw new Error('image unavailable');setAiMessages(prev=>[...prev,{role:'assistant',text:'تصویر آماده شد ✨',imageUrl:data.imageUrl}]);}else{const answer=data?.answer||data?.choices?.[0]?.message?.content;if(!answer)throw new Error('empty response');setAiMessages(prev=>[...prev,{role:'assistant',text:answer}]);}}catch(err){setAiMessages(prev=>[...prev,{role:'assistant',text:isImage?'ساخت تصویر فعلاً در دسترس نیست. بررسی کن کلید OpenAI و دسترسی مدل تصویر در سرور تنظیم باشند.':'فعلاً نتونستم وصل بشم. لطفاً کمی بعد دوباره تلاش کن.'}]);}finally{setAiLoading(false);}}
