 function addAdminByUsername(e){e.preventDefault();const username=newAdminUsername.trim().replace(/^@/,'').toLowerCase();if(!isOwner){setNotice('فقط مالک وایرو می‌تواند ادمین اضافه کند.');return}if(!/^[a-z0-9_.]{3,24}$/.test(username)){setNotice('نام کاربری معتبر نیست.');return}if(adminUsers.some(u=>u.username===username&&u.status==='active')){setNotice('این کاربر از قبل ادمین است.');return}setAdminUsers(v=>[...v,{id:'admin-'+Date.now(),name:username,username,status:'active',role:'admin'}]);setNewAdminUsername('');setNotice('ادمین در پیش‌نمایش این مرورگر اضافه شد. برای اعمال امن بین همهٔ کاربران باید نقش در دیتابیس سرور ثبت شود.');}
